class Cart:
    def __init__(self):
        self._lines = {}                      # item -> [price, quantity]

    def add(self, item, price, quantity=1):
        if quantity < 1:
            raise ValueError("Quantity must be at least 1")
        if item in self._lines:
            self._lines[item][1] += quantity   # the first price stays
        else:
            self._lines[item] = [price, quantity]

    def remove(self, item):
        return self._lines.pop(item, None) is not None

    def quantity_of(self, item):
        return self._lines[item][1] if item in self._lines else 0

    def item_count(self):
        return sum(quantity for _, quantity in self._lines.values())

    def total(self):
        return round(sum(price * quantity for price, quantity in self._lines.values()), 2)
